def build_dataset():
    output_path = os.path.join("datasets", "kisanroute_queries.csv")
    fieldnames = ["query_id", "query_text", "category", "sub_topic", "crop"]
    
    with open(output_path, mode="w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        
        category_counters = {}
        for idx, (cat, sub_topic, crop, query) in enumerate(QUERIES_DATA, 1):
            category_counters[cat] = category_counters.get(cat, 0) + 1
            code_prefix = "".join([w[0].upper() for w in cat.split()[:2]])
            query_id = f"KR-{code_prefix}-{category_counters[cat]:03d}"
            writer.writerow({
                "query_id": query_id,
                "query_text": query.strip(),
                "category": cat.strip(),
                "sub_topic": sub_topic.strip(),
                "crop": crop.strip()
            })
            
    print(f"Dataset successfully compiled to: {output_path}")
    print(f"Total samples: {len(QUERIES_DATA)}")
    for cat, count in category_counters.items():
        print(f"  - {cat}: {count} samples")

if __name__ == "__main__":
    build_dataset()

